vulnerable_code:
app.post('/api/profile/deleteBulk', async (req, res) => {
  await Profile.deleteMany({ _id: { $in: req.body.ids } });
  res.send('Bulk deleted');
});

corrected_code:
app.post('/api/profile/deleteBulk', async (req, res) => {
  await Profile.deleteMany({ _id: { $in: req.body.ids }, ownerId: req.user.id });
  res.send('Bulk deleted');
});
